<script setup>
import { reactive, ref, computed, watch } from 'vue'
import { useRouter } from 'vue-router'
import { call, Button, toast } from 'frappe-ui'
import SelectMenu from '../components/SelectMenu.vue'

const router = useRouter()

const JENIS_OPTIONS = ['Pengurangan Bunga', 'Pengurangan Denda', 'Pengurangan Bunga & Denda']

const form = reactive({
	no_perjanjian: '',
	jenis_deviasi: '',
	pengurangan_denda: 0,
	pengurangan_bunga: 0,
	pengurangan_admin: 0,
	alasan: '',
})
const nasabah = reactive({ nama_nasabah: '', cabang: '', no_hp: '', plafond: null })
const rincian = reactive({
	sisa_pokok: 0,
	sisa_bunga: 0,
	sisa_admin: 0,
	total_sisa_angsuran: 0,
	total_denda: 0,
	saldo_tabungan: 0,
	total_hutang: 0,
	sisa_os: 0,
})
const cekDone = ref(false)

function num(v) {
	const n = Number(v)
	return Number.isFinite(n) ? n : 0
}

// ---- Pencarian No Perjanjian (Master Data Nasabah, status Aktif) ----
const searchQuery = ref('')
const searchOpen = ref(false)
const searching = ref(false)
const searchResults = ref([])
let searchTimer = null

function onSearchFocus() {
	searchOpen.value = true
	if (!searchResults.value.length) fetchNasabah('')
}
function onSearch() {
	searchOpen.value = true
	clearTimeout(searchTimer)
	searchTimer = setTimeout(() => fetchNasabah(searchQuery.value), 300)
}
async function fetchNasabah(q) {
	searching.value = true
	try {
		const params = {
			doctype: 'Master Data Nasabah',
			filters: JSON.stringify([['status', '=', 'Aktif']]),
			fields: JSON.stringify(['name', 'nama_nasabah']),
			order_by: 'modified desc',
			limit_page_length: 20,
		}
		const t = (q || '').trim()
		if (t)
			params.or_filters = JSON.stringify([
				['name', 'like', `%${t}%`],
				['nama_nasabah', 'like', `%${t}%`],
			])
		searchResults.value = (await call('frappe.client.get_list', params)) || []
	} catch (e) {
		searchResults.value = []
	} finally {
		searching.value = false
	}
}
async function selectNasabah(r) {
	form.no_perjanjian = r.name
	searchQuery.value = r.name
	searchOpen.value = false
	// Reset rincian & isi info nasabah (mirip fetch_from Frappe).
	cekDone.value = false
	Object.assign(rincian, {
		sisa_pokok: 0,
		sisa_bunga: 0,
		sisa_admin: 0,
		total_sisa_angsuran: 0,
		total_denda: 0,
		saldo_tabungan: 0,
		total_hutang: 0,
		sisa_os: 0,
	})
	form.pengurangan_denda = 0
	form.pengurangan_bunga = 0
	form.pengurangan_admin = 0
	try {
		const d = await call('frappe.client.get_value', {
			doctype: 'Master Data Nasabah',
			filters: r.name,
			fieldname: JSON.stringify(['nama_nasabah', 'cabang', 'no_hp_1', 'pinjaman']),
		})
		nasabah.nama_nasabah = d?.nama_nasabah || r.nama_nasabah || ''
		nasabah.cabang = d?.cabang || ''
		nasabah.no_hp = d?.no_hp_1 || ''
		nasabah.plafond = d?.pinjaman ?? null
	} catch (e) {
		nasabah.nama_nasabah = r.nama_nasabah || ''
	}
}

// Snackbar sendiri (bukan toast frappe-ui): timer auto-dismiss bawaan reka-ui
// ikut fokus window & di webview (Capacitor/Android) sering dianggap tak fokus,
// jadi toast tak pernah hilang sendiri. Snackbar ini punya animasi keluar via
// <Transition> dan hilang sendiri lewat setTimeout.
const snack = reactive({ show: false, type: 'success', message: '' })
let snackTimer = null
function autoToast(type, message) {
	if (snackTimer) clearTimeout(snackTimer)
	snack.type = type
	snack.message = message
	snack.show = true
	snackTimer = setTimeout(() => {
		snack.show = false // memicu animasi keluar
	}, 3500)
}

// ---- Cek Rincian Hutang (read-only, live n8n) ----
const checking = ref(false)
async function cekRincian() {
	if (!form.no_perjanjian) {
		autoToast('error', 'Pilih No Perjanjian dulu.')
		return
	}
	if (checking.value) return
	checking.value = true
	try {
		const d = await call('juragan.api.portal.deviasi.cek_rincian_hutang_baru', {
			no_perjanjian: form.no_perjanjian,
		})
		Object.assign(rincian, d?.rincian || {})
		if (d?.nasabah) {
			nasabah.nama_nasabah = d.nasabah.nama_nasabah || nasabah.nama_nasabah
			nasabah.cabang = d.nasabah.cabang || nasabah.cabang
			nasabah.no_hp = d.nasabah.no_hp_1 || nasabah.no_hp
			nasabah.plafond = d.nasabah.pinjaman ?? nasabah.plafond
		}
		// Clamp pengurangan ke maksimum baru.
		form.pengurangan_denda = Math.min(num(form.pengurangan_denda), num(rincian.total_denda))
		form.pengurangan_bunga = Math.min(num(form.pengurangan_bunga), num(rincian.sisa_bunga))
		form.pengurangan_admin = Math.min(num(form.pengurangan_admin), num(rincian.sisa_admin))
		cekDone.value = true
		autoToast('success', 'Rincian hutang berhasil diambil')
	} catch (e) {
		autoToast('error', e?.messages?.[0] || e?.message || 'Gagal mengambil rincian hutang')
	} finally {
		checking.value = false
	}
}

// ---- Editability pengurangan (ikut read_only_depends_on doctype) ----
const dendaEditable = computed(() =>
	['Pengurangan Denda', 'Pengurangan Bunga & Denda'].includes(form.jenis_deviasi)
)
const bungaEditable = computed(() =>
	['Pengurangan Bunga', 'Pengurangan Bunga & Denda'].includes(form.jenis_deviasi)
)
const adminEditable = computed(() =>
	['Pengurangan Bunga', 'Pengurangan Bunga & Denda'].includes(form.jenis_deviasi)
)
// Ganti jenis → nolkan pengurangan yang tak berlaku.
watch(
	() => form.jenis_deviasi,
	() => {
		if (!dendaEditable.value) form.pengurangan_denda = 0
		if (!bungaEditable.value) form.pengurangan_bunga = 0
		if (!adminEditable.value) form.pengurangan_admin = 0
	}
)

const penguranganFields = computed(() => [
	{
