// ---- Simpan ----
const saving = ref(false)
async function save() {
	if (!form.no_perjanjian) return autoToast('error', 'No Perjanjian wajib diisi.')
	if (!form.jenis_deviasi) return autoToast('error', 'Jenis Deviasi wajib diisi.')
	if (saving.value) return
	saving.value = true
	try {
		const doc = {
			doctype: 'Deviasi',
			no_perjanjian: form.no_perjanjian,
			jenis_deviasi: form.jenis_deviasi,
			// rincian dari cek (dikirim seperti alur desk; backend memvalidasi ulang)
			sisa_pokok: num(rincian.sisa_pokok),
			sisa_bunga: num(rincian.sisa_bunga),
			sisa_admin: num(rincian.sisa_admin),
			total_sisa_angsuran: num(rincian.total_sisa_angsuran),
			total_denda: num(rincian.total_denda),
			saldo_tabungan: num(rincian.saldo_tabungan),
			total_hutang: num(rincian.total_hutang),
			sisa_os: num(rincian.sisa_os),
			sisa_pokok_akhir: num(rincian.sisa_pokok),
			pengurangan_denda: num(form.pengurangan_denda),
			pengurangan_bunga: num(form.pengurangan_bunga),
			pengurangan_admin: num(form.pengurangan_admin),
			alasan: form.alasan,
		}
		const res = await call('frappe.client.insert', { doc: JSON.stringify(doc) })
		autoToast('success', `Deviasi ${res?.name || ''} berhasil dibuat`.trim())
		router.replace({ name: 'DeviasiDetail', params: { name: res.name } })
	} catch (e) {
		autoToast('error', e?.messages?.[0] || e?.message || 'Gagal menyimpan Deviasi.')
	} finally {
		saving.value = false
	}
}

// ---- Helpers ----
const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
const todayLabel = computed(() => {
	const d = new Date()
	return `${String(d.getDate()).padStart(2, '0')} ${ID_MONTHS[d.getMonth()]} ${d.getFullYear()}`
})
function fmtRp(v) {
	if (v == null || v === '') return '-'
	const n = Number(v)
	if (!Number.isFinite(n)) return String(v)
	return 'Rp ' + new Intl.NumberFormat('id-ID', { maximumFractionDigits: 0 }).format(n)
}
function initials(name) {
	if (!name) return '?'
	return name.trim()[0]?.toUpperCase() || '?'
}
function goBack() {
	router.push({ name: 'Deviasi' })
}
